import { readFileSync, writeFileSync } from "node:fs";
import { globSync } from "node:fs";

const OLD = "disableTooltip";
const NEW = "hideHint";
const TARGET_TAGS = new Set([ "app-pill", "app-fancy-pill", "app-status-pill" ]);

const isSpace = c => c === " " || c === "\t" || c === "\n" || c === "\r";

/** Returns list of {start,end} byte ranges of attribute *names* to rename inside target tags. */
function attributeNameRanges(text) {
    const ranges = [];
    for (let i = 0; i < text.length; i++) {
        if (text[i] !== "<") continue;
        const m = /^<([a-zA-Z][\w-]*)/.exec(text.slice(i, i + 40));
        if (!m) continue;
        const tag = m[1];
        let j = i + m[0].length;
        if (!TARGET_TAGS.has(tag)) { i = j - 1; continue; }
        // walk attributes until the tag closes
        while (j < text.length) {
            while (j < text.length && isSpace(text[j])) j++;
            if (j >= text.length) break;
            if (text[j] === ">") { j++; break; }
            if (text[j] === "/" && text[j + 1] === ">") { j += 2; break; }
            const nameStart = j;
            while (j < text.length && !isSpace(text[j]) && text[j] !== "=" && text[j] !== ">" &&
                   !(text[j] === "/" && text[j + 1] === ">")) j++;
            const name = text.slice(nameStart, j);
            let k = j;
            while (k < text.length && isSpace(text[k])) k++;
            if (text[k] === "=") {
                k++;
                while (k < text.length && isSpace(text[k])) k++;
                if (text[k] === '"' || text[k] === "'") {
                    const q = text[k];
                    const close = text.indexOf(q, k + 1);
                    k = close === -1 ? text.length : close + 1;
                } else {
                    while (k < text.length && !isSpace(text[k]) && text[k] !== ">") k++;
                }
                j = k;
            }
            if (name === OLD) ranges.push({ start: nameStart, end: nameStart + OLD.length });
            else if (name === `[${OLD}]`) ranges.push({ start: nameStart + 1, end: nameStart + 1 + OLD.length });
            if (name === "" ) j++; // safety against stalling
        }
        i = j - 1;
    }
    return ranges;
}

function renameInTemplate(text) {
    const ranges = attributeNameRanges(text);
    let out = text;
    for (let r = ranges.length - 1; r >= 0; r--) {
        out = out.slice(0, ranges[r].start) + NEW + out.slice(ranges[r].end);
    }
    // template-ref reads on fancy pills
    out = out.replace(/\bfancyRef\.disableTooltip\b/g, `fancyRef.${NEW}`);
    return out;
}

const files = globSync("src/**/*.{ts,html}");
let changed = 0;
for (const file of files) {
    const src = readFileSync(file, "utf8");
    let out = src;
    if (file.endsWith(".html")) {
        out = renameInTemplate(src);
    } else {
        // rewrite each inline template literal region
        const pieces = [];
        let pos = 0;
        const re = /template:\s*`/g;
        let m;
        while ((m = re.exec(src)) !== null) {
            const bodyStart = m.index + m[0].length;
            const bodyEnd = src.indexOf("`", bodyStart);
            if (bodyEnd === -1) break;
            pieces.push(src.slice(pos, bodyStart));
            pieces.push(renameInTemplate(src.slice(bodyStart, bodyEnd)));
            pos = bodyEnd;
            re.lastIndex = bodyEnd;
        }
        pieces.push(src.slice(pos));
        out = pieces.join("");
    }
    if (out !== src) { writeFileSync(file, out); changed++; }
}
console.log("files changed:", changed);

