node -e '
const {globSync,readFileSync,writeFileSync}=require("fs");
let n=0;
for(const f of globSync("src/app/features/**/*.ts")){
  const s=readFileSync(f,"utf8");
  let o=s
   .replace(/\b(fancy|firstPill)\(\)(\??)\.disableTooltip\b/g,"$1()$2.hideHint")
   .replace(/\bpill\.disableTooltip\b/g,"pill.hideHint")
   .replace(/\bfancy\.disableTooltip\b/g,"fancy.hideHint");
  if(o!==s){writeFileSync(f,o);n++;}
}
console.log("ts refs updated in",n,"files");
'

